//! Box enumeration against the frozen references (the five-loop boxes are TEST DATA: generated by the test helper
//! from the band presets, then enumerated by the generic library code).
//!
//! By default (frozen tree `WS/fixtures/helper-k3-20261113`, `RUSTRED_K3_FIXTURES`, else SKIP): T162 box B = the
//! tree's `F1_box_all` key by key; T178 box = the in-box rows of `F5_closure_all`; T266 box: count formula and full
//! streaming enumeration (time and peak memory printed).
//! `#[ignore]` (needs `RUSTRED_CAMPAIGN_FIXTURES`, layout in `tests/cover_fixtures.rs`): dispatch over the ENUMERATED
//! boxes: T162 54,714 / 990; T178 409 uncovered, per-piece wins, 1,381 used records.

mod box_common;
mod k3_common;

use std::collections::{BTreeMap, HashSet};
use std::io::BufRead;
use std::path::PathBuf;

use box_common::*;
use rustred_campaign_core::boxdef::winner::{StreamOptions, usage};
use rustred_campaign_core::cover::{Dispatcher, Table};
use rustred_campaign_core::domain::{DomainOptions, TargetSource};
use rustred_campaign_core::key::{Key, NodeFrame};
use rustred_campaign_core::record::{ReadOptions, read_bank_predicates, read_table_file};

#[test]
fn t162_box_b_equals_frozen_f1_box_all() {
    let Some(o) = k3_common::oracle() else { return };
    let b = rstar_union(&lines_first(20, 9));
    let t0 = std::time::Instant::now();
    let mut mine: Vec<Key> = b.iter().collect();
    let secs = t0.elapsed().as_secs_f64();
    assert_eq!(mine.len(), 55_704);
    assert_eq!(b.count(), 55_704);
    mine.sort();
    let mut refk: Vec<Key> = o
        .jsonl("T162/F1_box_all.jsonl.gz")
        .iter()
        .map(|v| k3_common::as_key(&v[0]))
        .collect();
    refk.sort();
    assert_eq!(refk.len(), 55_704);
    assert_eq!(mine, refk, "T162 box B differs from F1_box_all");
    println!("T162 box B: 55,704 keys enumerated in {secs:.3}s = F1_box_all key by key");
}

#[test]
fn t178_box_equals_frozen_closure_box_rows() {
    let Some(o) = k3_common::oracle() else { return };
    let b = rstar_union(&lines_first(20, 10));
    assert_eq!(b.count(), 286_066);
    let mut mine: Vec<Key> = b.iter().collect();
    assert_eq!(mine.len(), 286_066);
    mine.sort();
    let rows = o.jsonl("T178B/F5_closure_all.jsonl.gz");
    assert_eq!(rows.len(), 330_287);
    let mut inbox: Vec<Key> = vec![];
    let mut outside_in_box = 0;
    for v in &rows {
        let k = k3_common::as_key(&v[0]);
        let flag = v[3].as_bool().expect("in_box");
        if flag {
            inbox.push(k);
        } else if b.contains(&k) {
            outside_in_box += 1;
        }
    }
    inbox.sort();
    assert_eq!(inbox.len(), 286_066);
    assert_eq!(
        mine, inbox,
        "T178 box differs from the in-box rows of F5_closure_all"
    );
    assert_eq!(outside_in_box, 0, "a row flagged outside lies in the box");
    println!(
        "T178 box: 286,066 keys = in-box rows of F5_closure_all; the 44,221 other rows are all outside"
    );
}

#[test]
fn t266_box_count_and_streaming_enumeration() {
    let b = rstar_union(&lines_first(20, 14));
    assert_eq!(b.count(), 5_250_168);
    let t0 = std::time::Instant::now();
    let mut n: u64 = 0;
    let mut layers: BTreeMap<(i32, i32), u128> = BTreeMap::new();
    let mut prev: Option<Key> = None;
    let mut sorted_within_layer = true;
    b.for_each_key(|k| {
        n += 1;
        let d: i32 = k[..14].iter().map(|x| x - 1).sum();
        let r: i32 = k[14..].iter().map(|x| -x).sum();
        *layers.entry((d, r)).or_insert(0) += 1;
        if let Some(p) = &prev {
            let pd: i32 = p[..14].iter().map(|x| x - 1).sum();
            let pr: i32 = p[14..].iter().map(|x| -x).sum();
            if (pd, pr) == (d, r) && p.as_slice() >= k {
                sorted_within_layer = false;
            }
        }
        prev = Some(k.to_vec());
    });
    let secs = t0.elapsed().as_secs_f64();
    assert_eq!(n, 5_250_168);
    assert!(sorted_within_layer);
    let want: BTreeMap<(i32, i32), u128> = b
        .layer_counts()
        .iter()
        .map(|c| ((c.dots as i32, c.rank as i32), c.count))
        .collect();
    assert_eq!(layers, want);
    assert_eq!(layers.len(), 39);
    // contains() on a strided sample (every 97th key) and its complement checks at the box edge
    let mut checked = 0;
    for (i, k) in b.iter().enumerate() {
        if i % 97 == 0 {
            assert!(b.contains(&k));
            checked += 1;
        }
    }
    let mut edge = vec![1i32; 14];
    edge.extend([0, 0, 0, 0, 0, -7]);
    assert!(!b.contains(&edge), "D = 0, r = 7 is outside");
    edge[0] = 2;
    assert!(b.contains(&edge), "D = 1, r = 7 is inside");
    println!(
        "T266 box: count formula 5,250,168; streaming enumeration {n} keys in {secs:.2}s (39 layers = layer_counts), {checked} contains checks; VmHWM {:?} kB",
        vm_hwm_kb()
    );
}

// ------------------------------------------------------------------------------------------------ dispatch

fn fixtures() -> PathBuf {
    PathBuf::from(
        std::env::var("RUSTRED_CAMPAIGN_FIXTURES")
            .expect("set RUSTRED_CAMPAIGN_FIXTURES (see tests/cover_fixtures.rs)"),
    )
}

fn key_lines(p: PathBuf) -> HashSet<Key> {
    let f = std::io::BufReader::new(std::fs::File::open(&p).expect("open"));
    f.lines()
        .map(|l| {
            let v: serde_json::Value = serde_json::from_str(&l.unwrap()).unwrap();
            k3_common::as_key(&v)
        })
        .collect()
}

pub fn t162_bank_dispatcher() -> Dispatcher {
    let fx = fixtures();
    let mut bank = read_bank_predicates(fx.join("T162/RULE-PREDICATES2440.json")).unwrap();
    bank.sort_by_key(|p| p.global_ordinal0);
    let table = Table::from_bank(
        "T162-bank-qualified",
        "T162/RULE-PREDICATES2440.json",
        &bank,
        20,
        TargetSource::CanonicalByConstruction {
            attestation: "T162 bank: no target field, presented slots, no recenter or permutation",
        },
    )
    .unwrap();
    Dispatcher::new(vec![table], vec![0]).unwrap()
}

pub fn t178_tables() -> (Vec<String>, Vec<Table>) {
    let fx = fixtures();
    let cfg: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(fx.join("T178B/cfg_t178_regenB.json")).unwrap(),
    )
    .unwrap();
    let (mut names, mut tables) = (vec![], vec![]);
    for t in cfg["tables"].as_array().unwrap() {
        let rel = t.as_str().unwrap().trim_start_matches("cases/t178B/");
        let tf = read_table_file(fx.join("T178B/cases").join(rel), ReadOptions::default()).unwrap();
        let name = rel.trim_end_matches(".jsonl").to_string();
        let table = Table::from_table_file(
            name.clone(),
            rel,
            &tf,
            DomainOptions {
                targets: TargetSource::CanonicalByConstruction {
                    attestation: "T178B case exports of engine table_dump.v1 tables",
                },
                // legacy reference numbers: exports carry no witness loci (re-audit RA-MAJOR-1, lane corefix2)
                witness: false,
                ..Default::default()
            },
        )
        .unwrap();
        names.push(name);
        tables.push(table);
    }
    (names, tables)
}

#[test]
#[ignore = "needs RUSTRED_CAMPAIGN_FIXTURES; run with --release -- --ignored"]
fn t162_dispatch_over_enumerated_box() {
    let b = rstar_union(&lines_first(20, 9));
    b.check_frame(&NodeFrame::without_header_lines_first(20, 9))
        .unwrap();
    let d = t162_bank_dispatcher();
    let o = StreamOptions {
        threads: 4,
        chunk: 4096,
    };
    let t0 = std::time::Instant::now();
    let rep = usage(&d, b.iter(), &o, true).unwrap();
    println!(
        "T162 over the enumerated box: {} keys, covered {} uncovered {} blocked {} undecided {} outside {}; used rules {}; {:.2}s",
        rep.keys,
        rep.covered,
        rep.uncovered,
        rep.blocked,
        rep.undecided,
        rep.outside_chart,
        rep.used_rules(),
        t0.elapsed().as_secs_f64()
    );
    assert_eq!(rep.keys, 55_704);
    assert_eq!((rep.covered, rep.uncovered, rep.open()), (54_714, 990, 990));
    let mine: HashSet<Key> = rep.open_keys.iter().map(|(k, _)| k.clone()).collect();
    assert_eq!(
        mine,
        key_lines(fixtures().join("T162/F1_uncovered_990.jsonl"))
    );
    let g = rustred_campaign_core::boxdef::group_by_face(&b.chart, mine.iter().cloned());
    println!("T162 uncovered: {} faces", g.faces.len());
    assert!(g.other.is_empty());
}

#[test]
#[ignore = "needs RUSTRED_CAMPAIGN_FIXTURES; run with --release -- --ignored"]
fn t178_dispatch_over_enumerated_box() {
    let b = rstar_union(&lines_first(20, 10));
    let (names, tables) = t178_tables();
    assert_eq!(tables.len(), 38);
    let d = Dispatcher::new(tables, (0..38).collect()).unwrap();
    let rep1 = usage(
        &d,
        b.iter(),
        &StreamOptions {
            threads: 1,
            chunk: 4096,
        },
        true,
    )
    .unwrap();
    let rep = usage(
        &d,
        b.iter(),
        &StreamOptions {
            threads: 4,
            chunk: 4096,
        },
        true,
    )
    .unwrap();
    assert_eq!(rep, rep1, "thread count changed the output");
    println!(
        "T178 over the enumerated box: {} keys, covered {} uncovered {} blocked {}; used records {}",
        rep.keys,
        rep.covered,
        rep.uncovered,
        rep.blocked,
        rep.used_rules()
    );
    assert_eq!(rep.keys, 286_066);
    assert_eq!((rep.covered, rep.uncovered, rep.blocked), (285_657, 409, 0));
    let mine: HashSet<Key> = rep.open_keys.iter().map(|(k, _)| k.clone()).collect();
    assert_eq!(
        mine,
        key_lines(fixtures().join("T178B/F5_box_uncovered_409.jsonl"))
    );
    let wins: BTreeMap<&str, u64> = names
        .iter()
        .map(String::as_str)
        .zip(rep.wins_per_table.iter().copied())
        .collect();
    for (n, w) in &wins {
        if *w > 0 {
            println!("  wins {n}: {w}");
        }
    }
    let r0 = names
        .iter()
        .position(|n| n.ends_with("R0"))
        .expect("R0 piece");
    assert_eq!(rep.wins_per_table[r0], 248_858);
    let g010 = names
        .iter()
        .position(|n| n.ends_with("rgq-g0-10"))
        .expect("rgq-g0-10");
    assert_eq!(rep.wins_per_table[g010], 10_160);
    assert_eq!(rep.wins_per_table.iter().sum::<u64>(), 285_657);
    assert_eq!(rep.used_rules(), 1_381);
}
